import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        StorageBox<String> nameBox = new StorageBox<>(sc.nextLine());
        nameBox.setValue(sc.nextLine());
        StorageBox<Integer> quantityBox = new StorageBox<>(Integer.parseInt(sc.nextLine().trim()));
        System.out.println("Product: " + nameBox.getValue());
        System.out.println("Quantity: " + quantityBox.getValue());
    }
}

class StorageBox<T> {
    private T value;

    StorageBox(T value) {
        this.value = value;
    }

    public void setValue(T value) {
        this.value = value;
    }

    public T getValue() {
        return value;
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int id = Integer.parseInt(sc.nextLine().trim());
        String name = sc.nextLine();
        Pair<Integer, String> customer = new Pair<>(id, name);
        System.out.println("Customer ID: " + customer.getFirst());
        System.out.println("Customer Name: " + customer.getSecond());
    }
}

class Pair<A, B> {
    private A first;
    private B second;

    Pair(A first, B second) {
        this.first = first;
        this.second = second;
    }

    public A getFirst() {
        return first;
    }

    public B getSecond() {
        return second;
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        Set<String> codes = new LinkedHashSet<>();
        for (int i = 0; i < n; i++) {
            codes.add(sc.nextLine());
        }
        StringBuilder out = new StringBuilder();
        out.append("Unique codes: ").append(codes.size()).append("\n");
        for (String code : codes) {
            out.append(code).append("\n");
        }
        System.out.print(out);
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.next());
        TreeSet<Integer> ids = new TreeSet<>();
        for (int i = 0; i < n; i++) {
            ids.add(Integer.parseInt(sc.next()));
        }
        StringBuilder line = new StringBuilder();
        for (int id : ids) {
            if (line.length() > 0) {
                line.append(' ');
            }
            line.append(id);
        }
        System.out.println("Distinct IDs: " + ids.size());
        System.out.println(line);
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        Map<String, Integer> counts = new HashMap<>();
        for (int i = 0; i < n; i++) {
            String name = sc.nextLine();
            counts.put(name, counts.getOrDefault(name, 0) + 1);
        }
        List<String> keys = new ArrayList<>(counts.keySet());
        Collections.sort(keys);
        StringBuilder out = new StringBuilder();
        out.append("Distinct categories: ").append(keys.size()).append("\n");
        for (String key : keys) {
            out.append(key).append(": ").append(counts.get(key)).append("\n");
        }
        System.out.print(out);
    }
}

import java.util.*;

public class Main {
    static <T> int firstIndex(List<T> values, T target) {
        for (int i = 0; i < values.size(); i++) {
            if (Objects.equals(values.get(i), target)) {
                return i;
            }
        }
        return -1;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        List<String> codes = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            codes.add(sc.nextLine());
        }
        String target = sc.nextLine();
        System.out.println(firstIndex(codes, target));
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int q = Integer.parseInt(sc.next());
        Repository<String> repo = new Repository<>();
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            String cmd = sc.next();
            if (cmd.equals("PUT")) {
                int id = Integer.parseInt(sc.next());
                repo.add(id, sc.next());
            } else if (cmd.equals("GET")) {
                String value = repo.get(Integer.parseInt(sc.next()));
                out.append(value == null ? "Not found" : value).append("\n");
            } else if (cmd.equals("DELETE")) {
                out.append(repo.remove(Integer.parseInt(sc.next())) ? "Deleted" : "Not found").append("\n");
            } else {
                out.append(repo.size()).append("\n");
            }
        }
        System.out.print(out);
    }
}

class Repository<T> {
    private Map<Integer, T> records = new HashMap<>();

    public void add(int id, T value) {
        records.put(id, value);
    }

    public T get(int id) {
        return records.get(id);
    }

    public boolean remove(int id) {
        return records.remove(id) != null;
    }

    public int size() {
        return records.size();
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int q = Integer.parseInt(sc.next());
        List<String> history = new ArrayList<>();
        int current = -1;
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            String cmd = sc.next();
            if (cmd.equals("VISIT")) {
                String url = sc.next();
                while (history.size() > current + 1) {
                    history.remove(history.size() - 1);
                }
                history.add(url);
                current = history.size() - 1;
            } else if (cmd.equals("BACK")) {
                if (current > 0) {
                    current--;
                }
            } else if (current < history.size() - 1) {
                current++;
            }
            out.append(current == -1 ? "No page" : history.get(current)).append("\n");
        }
        System.out.print(out);
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.next());
        List<Product> products = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            int id = Integer.parseInt(sc.next());
            int stock = Integer.parseInt(sc.next());
            products.add(new Product(id, stock));
        }
        Collections.sort(products);
        StringBuilder out = new StringBuilder();
        for (Product p : products) {
            out.append("ID: ").append(p.id).append(", Stock: ").append(p.stock).append("\n");
        }
        System.out.print(out);
    }
}

class Product implements Comparable<Product> {
    final int id;
    final int stock;

    Product(int id, int stock) {
        this.id = id;
        this.stock = stock;
    }

    @Override
    public int compareTo(Product other) {
        int byStock = Integer.compare(stock, other.stock);
        if (byStock != 0) {
            return byStock;
        }
        return Integer.compare(id, other.id);
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.next());
        List<Student> students = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            int id = Integer.parseInt(sc.next());
            int marks = Integer.parseInt(sc.next());
            students.add(new Student(id, marks));
        }
        students.sort(new Comparator<Student>() {
            @Override
            public int compare(Student a, Student b) {
                int byMarks = Integer.compare(b.marks, a.marks);
                if (byMarks != 0) {
                    return byMarks;
                }
                return Integer.compare(a.id, b.id);
            }
        });
        StringBuilder out = new StringBuilder();
        for (Student s : students) {
            out.append("ID: ").append(s.id).append(", Marks: ").append(s.marks).append("\n");
        }
        System.out.print(out);
    }
}

class Student {
    final int id;
    final int marks;

    Student(int id, int marks) {
        this.id = id;
        this.marks = marks;
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.next());
        TreeSet<Integer> slots = new TreeSet<>();
        for (int i = 0; i < n; i++) {
            slots.add(Integer.parseInt(sc.next()));
        }
        int q = Integer.parseInt(sc.next());
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            Integer found = slots.floor(Integer.parseInt(sc.next()));
            out.append(found == null ? "No appointment" : String.valueOf(found)).append("\n");
        }
        System.out.print(out);
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int q = Integer.parseInt(sc.next());
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            String cmd = sc.next();
            if (cmd.equals("ADD")) {
                queue.offer(Integer.parseInt(sc.next()));
            } else if (cmd.equals("PROCESS")) {
                Integer front = queue.poll();
                out.append(front == null ? "Queue empty" : String.valueOf(front)).append("\n");
            } else if (cmd.equals("NEXT")) {
                Integer front = queue.peek();
                out.append(front == null ? "Queue empty" : String.valueOf(front)).append("\n");
            } else {
                out.append(queue.size()).append("\n");
            }
        }
        System.out.print(out);
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int q = Integer.parseInt(sc.next());
        ActionStack<String> stack = new ActionStack<>();
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            String cmd = sc.next();
            if (cmd.equals("PUSH")) {
                stack.push(sc.next());
            } else if (cmd.equals("UNDO")) {
                out.append(stack.isEmpty() ? "Nothing to undo" : stack.pop()).append("\n");
            } else if (cmd.equals("PEEK")) {
                out.append(stack.isEmpty() ? "Nothing to undo" : stack.peek()).append("\n");
            } else {
                out.append(stack.isEmpty()).append("\n");
            }
        }
        System.out.print(out);
    }
}

class ActionStack<T> {
    private ArrayDeque<T> items = new ArrayDeque<>();

    public void push(T action) {
        items.push(action);
    }

    public T pop() {
        return items.pop();
    }

    public T peek() {
        return items.peek();
    }

    public boolean isEmpty() {
        return items.isEmpty();
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        Set<String> first = new HashSet<>();
        for (int i = 0; i < n; i++) {
            first.add(sc.nextLine());
        }
        int m = Integer.parseInt(sc.nextLine().trim());
        TreeSet<String> common = new TreeSet<>();
        for (int i = 0; i < m; i++) {
            String code = sc.nextLine();
            if (first.contains(code)) {
                common.add(code);
            }
        }
        if (common.isEmpty()) {
            System.out.println("No common products");
        } else {
            StringBuilder out = new StringBuilder();
            out.append("Common products: ").append(common.size()).append("\n");
            for (String code : common) {
                out.append(code).append("\n");
            }
            System.out.print(out);
        }
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.next());
        TreeMap<Integer, String> events = new TreeMap<>();
        for (int i = 0; i < n; i++) {
            int time = Integer.parseInt(sc.next());
            events.put(time, sc.next());
        }
        int q = Integer.parseInt(sc.next());
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            Integer key = events.floorKey(Integer.parseInt(sc.next()));
            if (key == null) {
                out.append("No event");
            } else {
                out.append(key).append(' ').append(events.get(key));
            }
            out.append("\n");
        }
        System.out.print(out);
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int capacity = Integer.parseInt(sc.next());
        int q = Integer.parseInt(sc.next());
        LRUCache<String, String> cache = new LRUCache<>(capacity);
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            String cmd = sc.next();
            if (cmd.equals("PUT")) {
                String key = sc.next();
                cache.put(key, sc.next());
            } else if (cmd.equals("GET")) {
                String value = cache.get(sc.next());
                out.append(value == null ? "Not found" : value).append("\n");
            } else {
                out.append(cache.size()).append("\n");
            }
        }
        System.out.print(out);
    }
}

class LRUCache<K, V> {
    private final LinkedHashMap<K, V> map;

    LRUCache(int capacity) {
        map = new LinkedHashMap<K, V>(16, 0.75f, true) {
            @Override
            protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
                return size() > capacity;
            }
        };
    }

    public V get(K key) {
        return map.get(key);
    }

    public void put(K key, V value) {
        map.put(key, value);
    }

    public int size() {
        return map.size();
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int q = Integer.parseInt(sc.next());
        PriorityQueue<Ticket> queue = new PriorityQueue<>(new Comparator<Ticket>() {
            @Override
            public int compare(Ticket a, Ticket b) {
                int byPriority = Integer.compare(a.priority, b.priority);
                if (byPriority != 0) {
                    return byPriority;
                }
                return Integer.compare(a.id, b.id);
            }
        });
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            String cmd = sc.next();
            if (cmd.equals("ADD")) {
                int priority = Integer.parseInt(sc.next());
                int id = Integer.parseInt(sc.next());
                queue.add(new Ticket(priority, id));
            } else {
                Ticket t = queue.poll();
                if (t == null) {
                    out.append("No pending tickets\n");
                } else {
                    out.append("Priority: ").append(t.priority).append(", ID: ").append(t.id).append("\n");
                }
            }
        }
        System.out.print(out);
    }
}

class Ticket {
    final int priority;
    final int id;

    Ticket(int priority, int id) {
        this.priority = priority;
        this.id = id;
    }
}

import java.util.*;

public class Main {
    static double sum(List<? extends Number> values) {
        double total = 0;
        for (Number value : values) {
            total += value.doubleValue();
        }
        return total;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String type = sc.next();
        int n = Integer.parseInt(sc.next());
        double total;
        if (type.equals("INT")) {
            List<Integer> values = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                values.add(Integer.parseInt(sc.next()));
            }
            total = sum(values);
        } else {
            List<Double> values = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                values.add(Double.parseDouble(sc.next()));
            }
            total = sum(values);
        }
        System.out.println("Sum: " + String.format(Locale.US, "%.2f", total));
    }
}

import java.util.*;
import java.util.function.Function;

public class Main {
    static <T, K extends Comparable<K>> Map<K, List<T>> groupBy(List<T> items, Function<T, K> keyFn) {
        Map<K, List<T>> groups = new TreeMap<>();
        for (T item : items) {
            groups.computeIfAbsent(keyFn.apply(item), k -> new ArrayList<>()).add(item);
        }
        return groups;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.next());
        List<Employee> employees = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            String name = sc.next();
            employees.add(new Employee(name, sc.next()));
        }
        Map<String, List<Employee>> groups = groupBy(employees, e -> e.department);
        StringBuilder out = new StringBuilder();
        for (Map.Entry<String, List<Employee>> entry : groups.entrySet()) {
            out.append("Department: ").append(entry.getKey()).append("\n");
            for (Employee e : entry.getValue()) {
                out.append("Employee: ").append(e.name).append("\n");
            }
        }
        System.out.print(out);
    }
}

class Employee {
    final String name;
    final String department;

    Employee(String name, String department) {
        this.name = name;
        this.department = department;
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int q = Integer.parseInt(sc.next());
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        Set<Integer> pending = new HashSet<>();
        Set<Integer> completed = new HashSet<>();
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            String cmd = sc.next();
            if (cmd.equals("ADD")) {
                int id = Integer.parseInt(sc.next());
                if (!pending.contains(id) && !completed.contains(id)) {
                    queue.offer(id);
                    pending.add(id);
                }
            } else if (cmd.equals("PROCESS")) {
                Integer id = queue.poll();
                if (id == null) {
                    out.append("No pending tasks\n");
                } else {
                    pending.remove(id);
                    completed.add(id);
                    out.append("Processed: ").append(id).append("\n");
                }
            } else if (cmd.equals("PENDING")) {
                out.append(queue.size()).append("\n");
            } else {
                out.append(completed.contains(Integer.parseInt(sc.next()))).append("\n");
            }
        }
        System.out.print(out);
    }
}
